def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if not alive:
        return float(min(budget, max(1.0, DAILY_SALARY * 0.35)))

    opp_bids = []
    credible_bids = []
    stressed_count = 0
    desperate_count = 0
    rich_aggressive_count = 0

    for agent_id, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        prev_bid = prev.get('bid')
        if prev_bid is not None:
            opp_bids.append(float(prev_bid))
            if opp['budget'] >= float(prev_bid) * 0.8:
                credible_bids.append(float(prev_bid))
        if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
            stressed_count += 1
        if opp.get('no_water_days', 0) >= 2 or opp.get('hp', 10) <= 2:
            desperate_count += 1
        if opp.get('budget', 0) >= 700 and prev_bid is not None and float(prev_bid) >= 90:
            rich_aggressive_count += 1

    highest_prev = max(opp_bids) if opp_bids else 0.0
    highest_credible = max(credible_bids) if credible_bids else highest_prev

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 0.8
    elif hp <= 4:
        urgency += 0.45
    if no_water_days >= 2:
        urgency += 0.8
    elif no_water_days >= 1:
        urgency += 0.35
    if day >= 8:
        urgency += 0.15
    if urgency > 1.2:
        urgency = 1.2

    target = DAILY_SALARY * (0.42 + 0.28 * scarcity + 0.22 * min(1.0, urgency))

    if supply <= 17:
        target = max(target, highest_credible + 2.5)
    elif supply <= 20:
        target = max(target, highest_credible + 1.0)
    else:
        target = max(target, min(highest_credible, DAILY_SALARY * 1.05) * 0.9)

    if stressed_count >= 2 and urgency < 0.5 and supply >= 20:
        target *= 0.82

    if desperate_count >= 2 and (hp <= 4 or no_water_days >= 1):
        target = max(target, highest_credible + 3.0)

    if rich_aggressive_count >= 1 and supply <= 18:
        target = max(target, highest_credible + 4.0)

    if hp >= 7 and no_water_days == 0 and supply >= 22 and highest_prev >= 95:
        target *= 0.72

    if hp <= 2 or no_water_days >= 2:
        target = max(target, DAILY_SALARY * 0.95)

    max_safe = budget
    if day < 10:
        reserve = max(0.0, (10 - day) * DAILY_SALARY * 0.18)
        max_safe = max(0.0, budget - reserve)
        if hp <= 3 or no_water_days >= 1:
            max_safe = budget

    if max_safe <= 0:
        max_safe = min(budget, DAILY_SALARY * 0.4)

    bid = min(target, max_safe)
    bid = max(0.0, min(bid, budget))

    if bid < 1.0 and budget >= 1.0:
        bid = 1.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    # Alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        # Conservative if alone
        return max(0, min(my_status.get('budget', 0), int(DAILY_SALARY * 0.4)))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    # Read yesterday bids from previous_trace
    yesterday_bids = []
    yesterday_high_pressure = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', None) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b_val = float(b)
            except Exception:
                continue
            yesterday_bids.append((oid, b_val))
            if b_val >= 0.9 * DAILY_SALARY:
                yesterday_high_pressure.append((oid, b_val))

    # Supply pressure: higher supply means water is easier to secure, so we can bid less.
    # Map supply in [15,25] to a multiplier in [1.05,0.85]
    if MAX_SUPPLY > MIN_SUPPLY:
        t = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        t = 0.5
    supply_mult = 1.05 - 0.20 * max(0.0, min(1.0, t))

    # Base bid: aim to outbid low-mid bidders but not chase Cindy too hard.
    if yesterday_bids:
        # Consider top 2 bids to gauge ceiling without overreacting.
        bids_only = [b for _, b in yesterday_bids]
        bids_only.sort()
        top_bid = bids_only[-1]
        second_top = bids_only[-2] if len(bids_only) >= 2 else bids_only[-1]

        # If someone was bidding very high (near salary), increase to avoid losing the last water.
        if yesterday_high_pressure:
            target = max(second_top + 1.0, 0.85 * DAILY_SALARY)
        else:
            # Otherwise, bid slightly above the second-highest to steal when Cindy is the only heavy bidder.
            target = min(top_bid - 1.0, second_top + 3.0)

        # If my HP is critical or I already have no-water days, be more aggressive.
        if my_hp <= 2 or my_no_water_days >= 2:
            target = max(target, 0.75 * DAILY_SALARY)

        bid = target * supply_mult
    else:
        # No trace info: use HP-driven baseline
        if my_hp <= 2 or my_no_water_days >= 2:
            bid = 0.85 * DAILY_SALARY
        else:
            bid = 0.55 * DAILY_SALARY
        bid *= supply_mult

    # Ensure integer bid and within budget.
    bid_int = int(bid)
    if my_budget <= 0:
        return 0

    # Never bid more than budget
    bid_int = min(bid_int, int(my_budget))

    # Safety floor: if we can, bid at least a small amount to avoid frequent starvation.
    if bid_int < 5 and my_budget >= 5:
        bid_int = 5

    return max(0, bid_int)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If I'm the only one left, bid minimally to save budget
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        # Ensure 'bid' is checked before access, and 'previous_trace' exists
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Decision logic based on yesterday's highest pressure and my HP
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # If yesterday's highest bid was very high, react
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            # If healthy, try to conserve budget by bidding lower (risky, but saves money)
            if my_status['hp'] > 3:
                return min(my_status['budget'], DAILY_SALARY * 0.3)
            # If low HP, bid very aggressively to survive
            return min(my_status['budget'], DAILY_SALARY * 0.95)

        # If yesterday's bids were moderate, bid slightly above the highest
        return min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5))

    # If no previous bids (e.g., Day 1 or all previous opponents died/had no trace)
    if my_status['hp'] <= 2: # Critical HP, bid aggressively
        return min(my_status['budget'], DAILY_SALARY * 0.9)

    # Default bid for healthy state or no strong previous bid signal
    return min(my_status['budget'], DAILY_SALARY * 0.55)

